import boto3
for r in ['{{REGION_A}}','{{REGION_B}}','{{REGION_C}}']:
    c=boto3.client('ec2',region_name=r)
    for p in c.get_paginator('describe_instances').paginate(Filters=[{'Name':'instance-state-name','Values':['running']}]):
        for res in p['Reservations']:
            for i in res['Instances']:
                n=[t['Value'] for t in i.get('Tags',[]) if t['Key']=='Name']
                print(r,i['InstanceId'],n[:1],i.get('PrivateIpAddress'))

import boto3,collections
c=collections.Counter()
for p in boto3.client('ec2').get_paginator('describe_instances').paginate():
    for r in p['Reservations']:
        for i in r['Instances']:
            c[i['State']['Name']]+=1
print(dict(c))

import boto3
for p in boto3.client('lambda').get_paginator('list_functions').paginate():
    for f in p['Functions']:
        print(f['FunctionName'],f.get('Runtime'),f['MemorySize'])

