import boto3,datetime as d
t=d.date.today()
r=boto3.client('ce').get_cost_and_usage(TimePeriod={'Start':str(t-d.timedelta(30)),'End':str(t)},Granularity='MONTHLY',Metrics=['UnblendedCost'],GroupBy=[{'Type':'DIMENSION','Key':'SERVICE'}])
for x in r['ResultsByTime']:
    for g in x['Groups']:
        print(g['Keys'][0],g['Metrics']['UnblendedCost']['Amount'])

